solutions.javascript:
const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < m; i++) {
  const a = tok[2 + 2 * i], b = tok[3 + 2 * i];
  adj[a].push(b);
  adj[b].push(a);
}
const color = new Array(n + 1).fill(-1);
let ok = true;
for (let s = 1; s <= n && ok; s++) {
  if (color[s] !== -1) continue;
  color[s] = 0;
  const queue = [s];
  for (let head = 0; head < queue.length && ok; head++) {
    const u = queue[head];
    for (const v of adj[u]) {
      if (color[v] === -1) { color[v] = color[u] ^ 1; queue.push(v); }
      else if (color[v] === color[u]) { ok = false; break; }
    }
  }
}
console.log(ok ? "YES" : "NO");

